Lemma disp_round : forall p cf, AT BP_DISP (fun st => st <> 11) p cf -> p < p1 -> as_SR H (RES p) cf.
Proof.
  open_X. intros p [ms mo] ATc PLT.
  destruct ATc as (rax & t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & t3 & t4 & t5 & t6 & s & d & m & XS
                   & VIS & STc & KREL & MP & INVc). cbn [cfg_ms cfg_model] in *. cbv beta in STc.
  pose proof INVc as (MI & _ & _ & _ & _ & FR & SD & PC & _ & _ & _ & _ & _ & _ & _ & L & _).
  pose proof FR as (j0 & j128 & j152 & ja & j48 & jb & j80 & jc & j112 & LOC & _). pose proof SD as (_ & _ & _ & ACP & _).
  pose proof (proj1 L) as PCOK. pose proof PCOK as (_ & _ & _ & _ & _ & _ & Stt & _).
  pose proof (stat_open H MX CX X XOK) as (_ & _ & _ & PAL & _).
  eapply (ahh_evt_then H HH); [exact KREL| exact VIS| eapply bp_dispatch; [exact PC| exact PCOK| exact LOC| exact ACP| exact PAL| exact MI]|].
  cbv beta. intros msF1 mo1 KREL1 MP1 (a1' & VIS1).
  assert (ATk : forall stc : Z -> Prop, stc (pc_state (ps_c d)) -> AT (bp_target (pc_state (ps_c d))) stc p (mkCfg msF1 mo1)).
  { intros stc K. unfold put_at. cbn [cfg_ms cfg_model].
    exists rax, t0, t1, t2, (wz (bp_target (pc_state (ps_c d)))), a1', a2, a3, a4, a5, a6, a7, t3, t4, t5, t6, s, d, m, XS.
    split; [exact VIS1|]. split; [exact K|]. split; [exact KREL1|]. split; [eapply (ah_mpres_trans H HH); [exact MP| exact MP1]| exact INVc]. }
  clear VIS1. cbn in Stt.
  destruct Stt as [ST|[ST|[ST|[ST|[ST|[ST|[ST|[ST|[ST|[ST|[]]]]]]]]]]]; rewrite <- ST in ATk, STc; unfold bp_target, bp_targets in ATk; cbn [nth Z.to_nat Pos.to_nat Pos.iter_op Nat.add] in ATk.
  - apply (round0 H HH MX CX MA MR PSL1 PSL2 ISL PF1 PF2 IPF FH X XOK p); [apply ATk; reflexivity| exact PLT].
  - apply (round1 H HH MX CX MA MR PSL1 PSL2 ISL PF1 PF2 IPF FH X XOK p). apply ATk; reflexivity.
  - apply (round2 H HH MX CX MA MR PF1 PF2 IPF FH X XOK p). apply ATk; reflexivity.
  - apply (round3 H HH MX CX MA MR CL OBINIT PB1 PB2 OBI X XOK p); [apply ATk; reflexivity| exact PLT].
  - apply (round4 H HH MX CX MA MR PB1 PB2 OBI X XOK p); [apply ATk; reflexivity| exact PLT].
  - apply (round7 H HH MX CX MA MR CL OBINIT ONFIN PF1 PF2 IPF PCH X XOK p); [apply ATk; reflexivity| exact PLT].
  - apply (round8 H HH MX CX MA MR ONFIN PF1 PF2 IPF PCH X XOK p). apply ATk; reflexivity.
  - apply (round9 H HH MX CX MA MR MEMSET OCB X XOK p); [apply ATk; reflexivity| exact PLT].
  - apply (round10 H HH MX CX MA MR ONFIN PF1 PF2 IPF X XOK p). apply ATk; reflexivity.
  - exfalso. apply STc. reflexivity.
Qed.

(* [comment removed for export] *)
Lemma loop : forall (k : nat) p cf, AT BP_DISP (fun st => st <> 11) p cf -> p < p1 -> p1 - p <= Z.of_nat k -> as_SR H DONE cf.
Proof.
  induction k as [|k IH]; intros p cf ATc PLT MEAS; [exfalso; clear - PLT MEAS; lia|].
  eapply (ah_seq H HH); [eapply disp_round; [exact ATc| exact PLT]|].
  intros cf' [D|(p' & LT & AT')]; [apply (ah_done H HH); exact D|].
  apply (IH p' cf' AT'); [clear - LT; lia| rewrite Nat2Z.inj_succ in MEAS; clear - LT MEAS; lia].
Qed.

